// Function to format markdown-style text to HTML
const formatMessageText = (text: string): string => {
  // Replace **text** with <strong>text</strong> for bold
  let formatted = text.replace(/\*\*([^*]+)\*\*/g, '<strong>$1</strong>');
  
  // Replace numbered lists (1. text) with proper list items
  formatted = formatted.replace(/^(\d+)\.\s+(.+)$/gm, '<li>$2</li>');
  
  // Wrap consecutive list items in <ol> tags
  formatted = formatted.replace(/(<li>.*<\/li>\n?)+/g, (match) => `<ol>${match}</ol>`);
  
  // Replace bullet points (- text or • text) with unordered list items
  formatted = formatted.replace(/^[-•]\s+(.+)$/gm, '<li>$1</li>');
  
  // Wrap consecutive bullet list items in <ul> tags
  formatted = formatted.replace(/(<li>.*<\/li>\n?)+/g, (match) => {
    // Only wrap if not already wrapped in <ol>
    if (!match.includes('<ol>')) {
      return `<ul>${match}</ul>`;
    }
    return match;
  });
  
  // Remove excessive line breaks (more than 2 consecutive newlines)
  formatted = formatted.replace(/\n{3,}/g, '\n\n');
  
  // Convert double line breaks to single break with minimal spacing
  formatted = formatted.replace(/\n\n/g, '<br/>');
  
  // Remove single line breaks that are not needed (except before/after lists)
  formatted = formatted.replace(/\n/g, ' ');
  
  return formatted;
};

