      en: `I understand you have women's health concerns. Let me help you with some guidance.

**Possible Medical Condition**
This could be menstrual irregularities, PCOS, hormonal imbalance, or gynecological issues. This is not a final diagnosis.

**Recommended Specialist**
Gynecologist for proper evaluation.

**General Guidance**
• Maintain menstrual hygiene
• Track menstrual cycle
• Regular exercise and healthy diet
• Manage stress levels
• Adequate sleep and rest
• Stay hydrated
• Regular health check-ups

**Common Medicines (General Guidance Only)**
For menstrual pain, Paracetamol 500mg may help.
Do NOT self-medicate with hormonal medications.
Consult gynecologist for proper treatment.
These are general suggestions only, not prescriptions.

**Basic Precautions**
• Use clean sanitary products
• Change pads/tampons regularly
• Maintain genital hygiene
• Wear cotton underwear
• Balanced diet with iron-rich foods
• Regular breast self-examination
• Annual gynecological check-ups

**Emergency Warning**
Seek immediate medical help if you have:
• Severe abdominal pain
• Heavy bleeding (soaking pad in 1 hour)
• Sudden severe pelvic pain
• Fever with pelvic pain
• Breast lump or changes
• Postmenopausal bleeding
Call 108 for emergencies.

Click on Find Doctor in the chatbot page

**Safety Note:** This guidance is informational and not a medical diagnosis. Please consult a gynecologist.`,
