      bn: { listening: 'এখন বলুন...', processing: 'AI আপনার অনুরোধ প্রক্রিয়া করছে...', normal: 'পাঠাতে Enter চাপুন • ভয়েস ইনপুটের জন্য মাইক ক্লিক করুন' },
      mr: { listening: 'आता बोला...', processing: 'AI तुमची विनंती प्रक्रिया करत आहे...', normal: 'पाठवण्यासाठी Enter दाबा • व्हॉइस इनपुटसाठी माइक क्लिक करा' },
      gu: { listening: 'હવે બોલો...', processing: 'AI તમારી વિનંતી પર પ્રક્રિયા કરી રહ્યું છે...', normal: 'મોકલવા માટે Enter દબાવો • વૉઇસ ઇનપુટ માટે માઇક ક્લિક કરો' },
      kn: { listening: 'ಈಗ ಮಾತನಾಡಿ...', processing: 'AI ನಿಮ್ಮ ವಿನಂತಿಯನ್ನು ಪ್ರಕ್ರಿಯೆಗೊಳಿಸುತ್ತಿದೆ...', normal: 'ಕಳುಹಿಸಲು Enter ಒತ್ತಿರಿ • ಧ್ವನಿ ಇನ್‌ಪುಟ್‌ಗಾಗಿ ಮೈಕ್ ಕ್ಲಿಕ್ ಮಾಡಿ' },
      ml: { listening: 'ഇപ്പോൾ സംസാരിക്കുക...', processing: 'AI നിങ്ങളുടെ അഭ്യർത്ഥന പ്രോസസ്സ് ചെയ്യുന്നു...', normal: 'അയയ്ക്കാൻ Enter അമർത്തുക • വോയ്‌സ് ഇൻപുട്ടിനായി മൈക്ക് ക്ലിക്ക് ചെയ്യുക' },
      pa: { listening: 'ਹੁਣ ਬੋਲੋ...', processing: 'AI ਤੁਹਾਡੀ ਬੇਨਤੀ ਦੀ ਪ੍ਰਕਿਰਿਆ ਕਰ ਰਿਹਾ ਹੈ...', normal: 'ਭੇਜਣ ਲਈ Enter ਦਬਾਓ • ਵੌਇਸ ਇਨਪੁੱਟ ਲਈ ਮਾਈਕ ਕਲਿੱਕ ਕਰੋ' },
